mapper.select:
SELECT u.user_id AS userId, u.avatar, u.username, u.mobile, u.nickname, r.rank_name AS rankName, s.add_time AS bindTime, 'salesman' AS customerType, COUNT(CASE WHEN o.order_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM aftersales a WHERE a.order_id = o.order_id) THEN o.order_id END) AS orderCount, COALESCE(SUM(GREATEST(COALESCE(o.paid_amount, 0) - COALESCE((SELECT SUM(rl.refund_amount) FROM refund_log rl WHERE rl.order_id = o.order_id), 0), 0)), 0) AS orderAmount, MAX(o.pay_time) AS lastOrderTime, COALESCE(sc.channel, '') AS channel, COALESCE(sc.remark, '') AS remark FROM salesman s INNER JOIN `user` u ON s.user_id = u.user_id LEFT JOIN user_rank r ON u.rank_id = r.rank_id LEFT JOIN salesman_customer sc ON sc.salesman_id = s.pid AND sc.user_id = s.user_id LEFT JOIN `order` o ON o.user_id = s.user_id AND o.pay_status = 2 AND o.shop_id = #{filter.shopId} AND o.pay_time >= UNIX_TIMESTAMP(CONCAT(#{filter.startTime}, ' 00:00:00')) AND o.pay_time <= UNIX_TIMESTAMP(CONCAT(#{filter.endTime}, ' 23:59:59')) WHERE s.pid = #{filter.salesmanId}
AND (u.nickname LIKE CONCAT('%', #{filter.keyword}, '%') OR u.username LIKE CONCAT('%', #{filter.keyword}, '%') OR u.mobile LIKE CONCAT('%', #{filter.keyword}, '%'))
GROUP BY u.user_id, u.avatar, u.username, u.mobile, u.nickname, r.rank_name, s.add_time, sc.channel, sc.remark ORDER BY s.add_time DESC, u.user_id DESC
